test("period claim counts scenario 3", { tag: '@functionality' }, async ({ browser }) => {
  const sheet = ui.sheetId();
  const pg_uma = await ui.userPage(browser, "uma", sheet);
  await ui.setToday(pg_uma, "2026-04-05");
  await ui.setSetting(pg_uma, "floor", "0.50");
  await ui.setSetting(pg_uma, "late-pct", "10.00");
  await ui.setSetting(pg_uma, "period-numbering-from", "2026-03-01");
  await ui.setSetting(pg_uma, "grace-days", "3");
  expect(await ui.addHoliday(pg_uma, "2026-03-13")).toBe(true);
  expect(await ui.addHoliday(pg_uma, "2026-03-24")).toBe(true);
  await ui.setSetting(pg_uma, "proof-threshold-A", "4.00");
  await ui.setSetting(pg_uma, "pot", "33.33");
  await ui.setSetting(pg_uma, "fiscal-start-month", "7");
  await ui.setSetting(pg_uma, "alert-threshold", "1.00");
  await ui.setSetting(pg_uma, "escalate-after", "1");
  await ui.setSetting(pg_uma, "proof-kinds", "receipt,photo");
  await ui.setSetting(pg_uma, "score-log", "on");
  await ui.setSetting(pg_uma, "pending-sla", "1");
  expect(await ui.addGrade(pg_uma, "D")).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "33.33"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "7.50"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "12.50"})).toBe(true);
  expect(await ui.generatePeriods(pg_uma, "2026-02-01", "2026-04-30")).toBe(3);
  const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "C"}));
  const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "B", "terms": "20"}));
  expect(await ui.addCrew(pg_uma, "C1", "Ada")).toBe(true);
  expect(await ui.addCrewMember(pg_uma, "C1", "Cam")).toBe(true);
  await ui.setSetting(pg_uma, "clerk-limit", "3.00");
  const c_ada_0 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "10.25", "ref": "inv 7"}));
  expect(await ui.addProof(pg_uma, c_ada_0)).toBe(true);
  expect(await ui.compareSheet(pg_uma, sheet)).toEqual(["A 0.00 0.00", "B 0.00 0.00", "C 0.00 0.00", "D 0.00 0.00"]);
  expect(await ui.claimAction(pg_uma, c_ada_0, "void")).toBe(true);
  expect(await ui.importOpenings(pg_uma, "Ada,2026-02,1.00")).toBe(1);
  expect(await ui.periodAction(pg_uma, "2026-04", "close")).toBe(true);
  await ui.refresh(pg_uma);
  expect(await ui.watch(pg_uma, p_cam, true)).toBe(true);
  expect(await ui.inlineGrade(pg_uma, p_cam, "B")).toBe(true);
  expect(await ui.retire(pg_uma, p_ada, "2026-03-01")).toBe(true);
  await ui.showRetired(pg_uma, true);
  expect(await ui.addClaim(pg_uma, p_ada, {"amount": "10.25", "note": "n", "tags": "b,a,a"})).toBeNull();
  expect(await ui.statement(pg_uma, p_ada)).toBe(true);
  expect(await ui.dups(pg_uma)).toEqual([]);
  expect(await ui.addNote(pg_uma, "")).toBe(false);
  await ui.refresh(pg_uma);
  expect(await ui.statement(pg_uma, p_cam)).toBe(true);
  await ui.setToday(pg_uma, "2026-04-10");
  expect(await ui.hold(pg_uma, p_cam, {"from": "2026-03-09", "to": "2026-03-28"})).toBe(true);

