cd ..; export PORT=3917 AUDIT_FILE=$PWD/.run/audit.log; bin/start; for i in $(seq 1 60); do curl -fsS localhost:3917/actuator/health >/dev/null 2>&1 && break; sleep 1; done; echo up
python3 - <<'EOF'
src=open('e2e/specs/acceptance.spec.ts').read().split('\n')
head='\n'.join(src[:4])
def make(name, start, stop, page, extra):
    body='\n'.join(src[start-1:stop-1])
    return head+'\ntest.describe("dbg",()=>{\n'+body.replace('{ tag: \'@functionality\' }, ','')+'\n'+extra+'\n  });\n});\n'
open('e2e/specs/zz-dbg3.spec.ts','w').write(make('3',1324,1435,'pg_uma','''    await ui.addClaim(pg_uma, p_ada, {"amount": "10.35", "date": "2026-02-10", "note": "n", "tags": "a"});
    await ui.refresh(pg_uma);
    console.log("DBG", await pg_uma.getByTestId("person-row-"+p_ada).innerText());'''))
open('e2e/specs/zz-dbg2.spec.ts','w').write(make('2',969,1047,'pg_wes','''    await pg_wes.getByTestId("setting-floor").fill("0.50");
    await pg_wes.getByTestId("setting-floor-from").fill("2026-03-20");
    await pg_wes.getByTestId("settings-save").click();
    await pg_wes.waitForTimeout(3000);
    console.log("DBG", JSON.stringify(await pg_wes.getByTestId("setting-floor-current").innerText()), await pg_wes.getByTestId("settings-error").innerText().catch(()=>"noerr"));'''))
EOF
cd e2e && npx playwright test zz-dbg 2>&1 | grep -A30 DBG | head -80

